function figureText(slide) {
  const v = slide.visual
  if (v?.type === 'bars') return v.items.map(i => `${i.label}: ${i.value} ${v.unit || ''}`).join('; ') + '. ' + v.caption
  if (v?.items) return v.items.map(i => `${i.title}: ${i.text}`).join('; ') + '. ' + v.caption
  if (v?.rows) return v.rows.map(row => row.join(' — ')).join('; ') + '. ' + v.caption
  if (v?.branches) return `${v.root}: ${v.branches.map(b => `${b.title}: ${b.items.join(', ')}`).join('; ')}. ${v.caption}`
  if (v?.nodes) return v.nodes.map(n => `${n.title}: ${n.text}`).join('; ') + '. ' + v.edges.map(e => e.label).join('; ') + '. ' + v.caption
  if (slide.rows) return slide.rows.map(row => row.join(' — ')).join('; ')
  return (slide.bullets || []).join(' ')
}

function setNote(pack, slide, script, questions, answer) {
  pack.notes[slide.id] = { ...pack.notes[slide.id], script, questions, answer,
    estimatedSeconds: Math.round(script.trim().split(/\s+/).length / 2.1 + (slide.task ? 60 : 20)) }
}

export function applySemester8Review(course, bank, pack) {
  for (const [ti, topicId] of topicIds.entries()) {
    const lecture = course.lectures.find(l => l.id === topicId)
    if (!lecture) throw new Error(`Missing reviewed lecture: ${topicId}`)
    const find = number => {
      const id = `${topicId}-s${String(number).padStart(3, '0')}`
      const slide = lecture.slides.find(s => s.id === id)
      if (!slide) throw new Error(`Missing reviewed slide: ${id}`)
      return slide
    }
    for (let qi = 0; qi < 8; qi++) {
      const spec = exercises[ti][qi], first = 13 + 11 * qi
      const [explain, setup, reasoning, result, error] = context[ti + 3][qi]
      const rule = find(first + 2)
      const pilotRule = ti === 3 && qi === 1
      if (!pilotRule) {
        rule.visual = structuredClone(diagrams[ti][qi])
        delete rule.body; delete rule.bullets
        setNote(pack, rule, `${figureText(rule)}\n\nРазберите механизм на исходном случае: ${setup} ${reasoning} ${result}\n\nГраница: ${error}`,
          `Как связаны элементы схемы в исходном случае: ${setup}`, `${reasoning} ${result}`)
      }
      // Do not announce the later single-choice case and its answer here.
      for (const offset of [0, 1, 3]) {
        const s = find(first + offset)
        const illustrated = offset === 3 && (s.visual || s.rows)
        const script = offset === 0 ? `Начните с исходной ситуации: ${setup}\n\nПопросите назвать нужные данные до раскрытия результата.`
          : offset === 1 ? `${explain}\n\nОбъясните применение к исходному случаю: ${setup} ${reasoning}`
            : illustrated ? `${figureText(s)}\n\nПопросите связать подписи и значения с допустимым выводом. ${spec.why}`
              : `${figureText(s)}\n\nРазбор исходного случая: ${setup} ${reasoning} ${result}`
        setNote(pack, s, script, illustrated ? 'Что непосредственно показывают подписи и значения этого примера?' : `Какие данные нужны для разбора: ${setup}`,
          illustrated ? `${figureText(s)} ${spec.why}` : `${reasoning} ${result}`)
      }
      const transfer = find(first + 4)
      transfer.body = spec.transfer[0]
      transfer.bullets = ['Сначала предположите исход; затем обоснуйте его механизмом и границей проверки.']
      setNote(pack, transfer, `Новая ситуация: ${spec.transfer[0]}\n\nДайте группе ответить до разбора. Ориентир после попытки: ${spec.transfer[1]}`,
        spec.transfer[0], spec.transfer[1])
      const warning = find(first + 5)
      setNote(pack, warning, `Разберите ограничение исходного решения: ${error}\n\n${spec.why}`, `Какое неверное заключение исключают исходные условия? ${setup}`, `${error} ${spec.why}`)
      const summary = find(first + 6)
      summary.body = spec.why
      setNote(pack, summary, `До самопроверки восстановите связь на исходном случае: ${setup} ${reasoning}\n\nНе зачитывайте условия и варианты следующего задания. Попросите назвать ограничение: ${error}`,
        `Какой вывод допустим именно для исходных условий: ${setup}`, result)

      const multi = find(first + 10)
      if (!(ti === 3 && qi === 2)) {
        const [prompt, texts] = spec.multi
        const options = texts.map((text, i) => ({ id: `o${i + 1}`, text }))
        const rotation = (ti + qi) % options.length
        multi.title = 'Выберите два обоснованных утверждения'
        multi.task = { id: multi.task.id, type: 'multiple', choose: 2, prompt: prompt + ' Выберите два ответа.', options: [...options.slice(rotation), ...options.slice(0, rotation)] }
        bank.keys[multi.task.id] = { type: 'multiple', correct: ['o1', 'o2'], explanation: spec.why,
          optionExplanations: Object.fromEntries(options.map((o, i) => [o.id, i < 2 ? `Верно. ${spec.why}` : `Это утверждение не следует из условия. ${spec.why}`])) }
        setNote(pack, multi, `Самостоятельная проверка: ${prompt}\n\nПосле попытки разберите два верных утверждения: ${texts.slice(0, 2).join(' ')}\n\n${spec.why}`, prompt, `${texts.slice(0, 2).join(' ')} ${spec.why}`)
      }
      const matching = find(first + 9)
      const options = spec.pairs.map(([, text], i) => ({ id: `o${i + 1}`, text }))
      matching.title = 'Свяжите понятия и технические роли'
      matching.task = { id: matching.task.id, type: 'matching', prompt: 'Установите четыре предметных соответствия. Каждому элементу подходит одна роль.',
        items: spec.pairs.map(([text], i) => ({ id: `i${i + 1}`, text })), options: [...options.slice(2), ...options.slice(0, 2)] }
      bank.keys[matching.task.id] = { type: 'matching', pairs: Object.fromEntries(spec.pairs.map((_, i) => [`i${i + 1}`, `o${i + 1}`])), explanation: spec.why }
      const solution = spec.pairs.map(pair => pair.join(' → ')).join('; ')
      setNote(pack, matching, `Попросите установить соответствия и объяснить различие двух соседних понятий.\n\nПосле самостоятельной попытки: ${solution}. ${spec.why}`,
        matching.task.prompt, `${solution}. ${spec.why}`)
      const short = find(first + 8)
      const [prompt, answer] = spec.short
      short.title = typeof answer === 'number' ? 'Вычислите по заданным условиям' : 'Назовите существенное понятие'
      short.task = { id: short.task.id, type: 'short', prompt: prompt + (typeof answer === 'number' ? ' Введите число.' : '') }
      bank.keys[short.task.id] = typeof answer === 'number' ? { type: 'short', numeric: { value: answer, tolerance: 0 }, explanation: spec.why }
        : { type: 'short', accepted: answer, explanation: spec.why }
      setNote(pack, short, `Дайте ответить без подсказки: ${prompt}\n\nРазберите ответ: ${typeof answer === 'number' ? answer : answer[0]}. ${spec.why}`,
        prompt, `${typeof answer === 'number' ? answer : answer.join(' / ')}. ${spec.why}`)
    }
  }

  const lecture = course.lectures.find(l => l.id === topicIds[0])
  const logIntro = lecture.slides.find(s => s.id.endsWith('-s010'))
  logIntro.title = 'Id, RecordId и ActivityId: разные роли'
  logIntro.body = 'Windows, только чтение: Get-WinEvent -LogName Application -MaxEvents 4 | Select-Object TimeCreated, Id, RecordId, ActivityId'
  delete logIntro.bullets
  logIntro.columns = ['Поле', 'Назначение', 'Ограничение']
  logIntro.rows = [['Id', 'Тип события', 'Не номер запроса'], ['RecordId', 'Запись журнала', 'Не сквозная операция'], ['ActivityId', 'GUID активности', 'Может отсутствовать']]
  setNote(pack, logIntro,
    'Показана команда чтения Windows Event Log. По умолчанию Get-WinEvent возвращает новые события первыми; для хронологии результаты сортируют или используют соответствующий режим запроса. Id обозначает тип события данного провайдера. RecordId различает записи журнала. ActivityId — отдельный GUID активности; его наличие зависит от источника. Не каждый источник заполняет ActivityId.\n\nКоманда не создаёт события учебного приложения. Для следующего разбора выдана синтетическая выборка LabApp. В ней requestId и result — пользовательские поля EventData. Их нельзя считать встроенными свойствами EventRecord. Если провайдер публикует ActivityId, сопоставление с requestId задаётся его схемой; автоматически приравнивать эти значения нельзя. На Windows реальные данные зависят от установленного провайдера и разрешённого доступа к журналу.',
    'Две записи имеют Id=1001. Доказывает ли это одну операцию?',
    'Нет: это один тип события. Связь операции ищут по ActivityId либо requestId приложения и проверяют источник, экземпляр и время.')
  const logExample = lecture.slides.find(s => s.id.endsWith('-s016'))
  logExample.title = 'Четыре записи: разделяем A17 и A18'
  logExample.body = 'Синтетический вывод LabApp в хронологическом порядке. requestId и result извлечены из EventData учебного провайдера.'
  delete logExample.bullets; delete logExample.visual
  logExample.columns = ['Время / Id', 'requestId', 'Событие / result']
  logExample.rows = [['10:14:00 / 1001', 'A17', 'Начало / started'], ['10:14:01 / 1001', 'A18', 'Начало / started'], ['10:14:03 / 1002', 'A17', 'Конец / failed'], ['10:14:04 / 1002', 'A18', 'Конец / accepted']]
  setNote(pack, logExample,
    'Это вымышленные записи одного экземпляра LabApp, а не результат запуска на проверенном Windows-стенде. Время показано в одной зоне, записи упорядочены. У обоих начал Id=1001, у обоих завершений Id=1002; одинаковый тип не объединяет разные операции. Отдельные записи могут иметь RecordId 81–84. Пользовательские EventData содержат requestId и result.\n\nСгруппируйте по A17: начало 10:14:00, failed в 10:14:03 — три секунды. По A18: начало 10:14:01, accepted в 10:14:04 — тоже три секунды, но другой исход. Длительность сама не определяет успех. Если известен ActivityId, нужен полный GUID и схема его связи с операцией; короткое A17 — requestId приложения, а не значение Windows ActivityId.\n\nДля получения пользовательских полей у конкретного провайдера изучают его схему и XML события через ToXml(); не выбирают произвольный номер Properties как универсальный requestId. При неизвестной корреляции сохраняют неоднозначность.',
    'Почему одинаковые Id=1001 не объединяют A17 и A18? Сколько длится A17 и каков её исход?',
    'Id обозначает тип «начало», requestId различает операции. A17 длится три секунды и завершается failed; A18 — отдельная операция с accepted. Связь с ActivityId зависит от схемы провайдера.')
  const metricExample = lecture.slides.find(s => s.id.endsWith('-s027'))
  metricExample.visual.caption = 'Три учебных замера времени ответа. Для гипотезы нужны связанные события; причину проверяют отдельным повтором.'
  setNote(pack, metricExample,
    'На графике время ответа: 180 мс в 10:00, 420 мс в 10:15 и 870 мс в 10:30. Это измерения задержки, не длина очереди и не число уникальных заявок. Сначала назовите сам наблюдаемый рост. Для гипотезы нужны события того же экземпляра и соответствующих операций с согласованным временем. Даже совпавшая ошибка журнала не доказывает причину без проверки механизма и контрольного повтора.\n\nПример накопительного счётчика из этого же блока решает другой вопрос: сколько событий произошло между замерами. Не суммируйте снимки состояния и не подменяйте ими число поступлений.',
    'Что непосредственно измерено на графике? Подтверждает ли рост причину задержки?',
    'Измерено время ответа в миллисекундах. Видна динамика трёх точек; конкретная причина не установлена. Для проверки нужны связанные события и различающий повтор.')

  const cryptoLecture = course.lectures.find(l => l.id === topicIds[3])
  const technicalMap = cryptoLecture.slides.find(s => s.id.endsWith('-s037'))
  technicalMap.title = 'Протокол, алгоритм, ключ и реализация'
  pack.notes[technicalMap.id].script += '\n\nВ обычном сертификатном обмене TLS 1.3 сервер подтверждает владение закрытым ключом подписью. Клиент проверяет доверие к сертификату, имя нужного узла и подпись. Участники выводят секретные ключи для защиты записей AEAD; закрытый ключ сертификата не передаётся как содержимое сеанса. Это разные роли ключевого обмена, аутентификации и шифрования записей. Поддержка алгоритма клиентом не означает, что именно он выбран текущим сеансом. Для карты фиксируют наблюдаемые параметры сеанса, а не рекламный список реализации.'
  pack.notes[technicalMap.id].estimatedSeconds = Math.round(pack.notes[technicalMap.id].script.trim().split(/\s+/).length / 2.1 + 20)

  const starters = [
    {
      title: 'Пустой журнал ещё не означает исправность', kicker: 'Сигнал и функция',
      rows: [['Записей нет', 'Проверяют источник, фильтр и окно'], ['Heartbeat приходит', 'Сигнал получен; результат операции неизвестен'], ['Операция не подтверждена', 'Её исход требует отдельного свидетельства']],
      script: 'Heartbeat здесь означает периодический сигнал работающего процесса. Он может поступать, пока полезная операция не выполняется: например, поток проверки жив, а обработка запросов остановилась. Пустая выборка журнала тоже неоднозначна: события могли отсутствовать, источник мог не писать или фильтр мог исключить нужные записи. Эти наблюдения относятся к разным участкам. Для вывода о функции нужно её наблюдаемое поведение; сам факт жизни процесса или отсутствие строк его не заменяет.',
      question: 'Что установлено по heartbeat и чего по нему пока нельзя сказать?',
      answer: 'Установлено получение сигнала процесса в заданный момент. Выполнение полезной операции этим не подтверждено; для неё нужно собственное свидетельство.',
      preparation: 'Три независимых наблюдения: пустая выборка, heartbeat процесса и отсутствие подтверждения операции. Не объединять их в готовый диагноз.',
    },
    {
      title: 'Копирование архива оценивают в контексте', kicker: 'Действие и контекст',
      rows: [['Копия по регламенту', 'Возможна штатная резервная операция'], ['Получатель неизвестен', 'Нужны полномочия, маршрут и состав данных'], ['Известно только «скопировано»', 'Для вывода об инциденте данных мало']],
      script: 'Рассматривается синтетический архив без реальных пользовательских данных. Копирование может быть предусмотренной резервной операцией. Если получатель неизвестен, появляется вопрос о разрешении передачи и затронутых данных, но неизвестность не доказывает нарушение. Нужны источник действия, получатель, полномочия и фактическое последствие. Одно название операции не устанавливает ни мотив человека, ни состоявшийся инцидент.',
      question: 'Какие сведения отличают штатное резервирование от возможной неразрешённой передачи?',
      answer: 'Регламент, полномочия, получатель, состав переданных данных и наблюдаемый результат. Одного факта копирования недостаточно.',
      preparation: 'Учебный архив и два контекста копирования; намерение и инцидент не назначаются по одному глаголу в записи.',
    },
    {
      title: 'Вложение, вход и папка: разные проверки', kicker: 'Объект и граница проверки',
      rows: [['Проверено вложение письма', 'Не установлены права на папку'], ['Вход пользователя выполнен', 'Не разрешён автоматически любой ресурс'], ['Папка открылась', 'Не подтверждена проверка её файлов антивирусом']],
      script: 'Каждая строка относится к своему объекту. Результат проверки вложения защитным средством ничего сам по себе не говорит о полномочиях пользователя в хранилище. Успешный вход относится к подтверждению заявленной идентичности, но не назначает все разрешения на ресурсы. Успешное открытие папки показывает исход доступа в данных условиях; оно не заменяет отдельное свидетельство антивирусной проверки файлов. Связь между средствами может быть настроена, но её наличие и действие требуют собственных данных.',
      question: 'Что подтверждено открытием папки и что остаётся неизвестным о её файлах?',
      answer: 'Подтверждён доступ к папке в проверенных условиях. Режим и результат антивирусной проверки файлов из этого не следуют.',
      preparation: 'Три объекта: вложение письма, вход пользователя и папка. Рассматривать только границы имеющихся свидетельств, без выдуманной общей политики.',
    },
    {
      title: 'Шифротекст и ключ — разные данные', kicker: 'Содержимое и возможность восстановления',
      rows: [['Шифротекст', 'Результат шифрования, а не сам ключ'], ['Единственный ключ утрачен', 'Восстановление может стать невозможным'], ['Хэш совпал', 'Это ещё не свидетельство секретности']],
      script: 'Шифротекст — результат шифрования содержимого. Ключ выполняет другую роль: он нужен для предусмотренного обратного преобразования и не заменяется самим зашифрованным файлом. Если единственный доступный ключ утрачен и другого механизма восстановления нет, сохранённый шифротекст может остаться недоступным владельцу. Совпадение хэша отвечает на вопрос о сравнении данных с выбранным эталоном; оно не устанавливает, кто способен прочитать содержимое. Поэтому наличие файла, возможность восстановления и секретность — разные утверждения.',
      question: 'Отвечает ли совпавший хэш на вопрос, кто способен прочитать содержимое?',
      answer: 'Нет. Совпадение относится к сравнению данных с эталоном. Для вывода о секретности нужны сведения о защите содержимого и доступе к средствам его восстановления.',
      preparation: 'Два условных объекта: зашифрованный файл и ключ. Значения секретов не нужны; сравниваются роли данных и границы свидетельств.',
    },
  ]
  for (const [index, starter] of starters.entries()) {
    const slide = course.lectures.find(l => l.id === topicIds[index]).slides.find(s => s.id.endsWith('-s011'))
    slide.title = starter.title
    slide.kicker = starter.kicker
    slide.columns = ['Наблюдение или параметр', 'Граница вывода']
    slide.rows = starter.rows
    delete slide.body; delete slide.bullets; delete slide.visual
    setNote(pack, slide, starter.script, starter.question, starter.answer)
    pack.notes[slide.id].preparation = starter.preparation
  }
}
